MERGE INTO INFRANEXUM_IAM_PERMISSION p USING (SELECT '019ffbda-1040-7001-8001-000000000001' ID,'rsot.schema.create' CODE,'create' ACTION_NAME,'ELEVATED' SENSITIVITY FROM dual UNION ALL SELECT '019ffbda-1041-7002-8002-000000000002','rsot.schema.read','read','NORMAL' FROM dual UNION ALL SELECT '019ffbda-1042-7003-8003-000000000003','rsot.schema.update','update','ELEVATED' FROM dual UNION ALL SELECT '019ffbda-1043-7004-8004-000000000004','rsot.schema.deprecate','deprecate','CRITICAL' FROM dual UNION ALL SELECT '019ffbda-1044-7005-8005-000000000005','rsot.schema.publish','publish','CRITICAL' FROM dual UNION ALL SELECT '019ffbda-1045-7006-8006-000000000006','rsot.audit','audit','ELEVATED' FROM dual) s ON (p.CODE=s.CODE AND p.ORGANIZATION_ID IS NULL) WHEN NOT MATCHED THEN INSERT (ID,ORGANIZATION_ID,CODE,RESOURCE_TYPE,ACTION_NAME,SENSITIVITY,SCOPE_KIND,SYSTEM_DEFINED,ACTIVE,CREATED_AT,UPDATED_AT,DELETED_AT) VALUES (s.ID,NULL,s.CODE,'rsot_schema',s.ACTION_NAME,s.SENSITIVITY,'PLATFORM',1,1,SYSTIMESTAMP,SYSTIMESTAMP,NULL);
MERGE INTO INFRANEXUM_IAM_ROLE_PERMISSION rp USING (SELECT '019ffbda-1001-7e80-9ec8-7580467e9a85' ROLE_ID,ID PERMISSION_ID FROM INFRANEXUM_IAM_PERMISSION WHERE ORGANIZATION_ID IS NULL AND CODE IN ('rsot.schema.create','rsot.schema.read','rsot.schema.update','rsot.schema.deprecate','rsot.schema.publish','rsot.audit')) s ON (rp.ROLE_ID=s.ROLE_ID AND rp.PERMISSION_ID=s.PERMISSION_ID) WHEN NOT MATCHED THEN INSERT (ROLE_ID,PERMISSION_ID) VALUES (s.ROLE_ID,s.PERMISSION_ID);
